def committed_identity(output):
    ids=re.findall(rb'^publish_paths\.sh: committed sha: ([0-9a-f]{40})\r?$',output,re.M)
    if len(ids)!=1:raise ValueError('missing/ambiguous exact publisher commit receipt; HEAD is not a substitute')
    return ids[0].decode('ascii')

PATHFILE_TRANSPORT='PATH=/usr/bin:/bin:$PATH; export PATH; mapfile -t reviewed_paths < "$3" || exit 1; exec "$1" "$2" "${reviewed_paths[@]}"'
def qualify_native_path_budget(paths):
    if not paths or any(not isinstance(p,str) or not p or '\n' in p or '\r' in p for p in paths):raise ValueError('missing/invalid explicit path set')
    # This publisher forwards all paths to native Windows Python internally.
    # The real long-list control exits126 there even after Bash mapfile succeeds.
    # A conservative path-only budget leaves room for executable/root/board/msg
    # arguments; it is a setup refusal, not a claim that all short runs pass.
    units=len(subprocess.list2cmdline(paths).encode('utf-16-le'))//2
    if units>24000:raise ValueError('native publisher path argv exceeds qualified24000 UTF16-unit budget; route explicit-path delivery to publisher owner, no unchanged long-list attempt')
    return dict(path_argv_utf16_units=units,limit=24000,limits='Conservative setup guard; actual publisher/health/commit checks still required')

def publisher_argv(pub,publisher,paths):
    # Windows cannot launch the229-member packet as a large direct argv (actual
    # harmless probe returned WinError206). Bash reads the exact UTF8/LF path set
    # as data and passes a quoted array to the unchanged supported publisher.
    budget=qualify_native_path_budget(paths)
    argfile=pub/'reviewed-publisher-paths-01.txt'
    with argfile.open('xb') as f:f.write(('\n'.join(paths)+'\n').encode('utf8'))
    args=[r'C:\Program Files\Git\bin\bash.exe','-c',PATHFILE_TRANSPORT,'_',
          publisher.relative_to(ROOT).as_posix(),(pub/'message.txt').relative_to(ROOT).as_posix(),argfile.relative_to(ROOT).as_posix()]
    return args,dict(pathfile=argfile.relative_to(ROOT).as_posix(),pathfile_sha256=hashlib.sha256(argfile.read_bytes()).hexdigest(),
                     transport_sha256=hashlib.sha256(PATHFILE_TRANSPORT.encode()).hexdigest(),explicit_paths=len(paths),native_path_budget=budget)

def verify_git_blobs(commit, expected, *, handoff_bytes=None):
    if not re.fullmatch('[0-9a-f]{40}',commit) or not expected:raise ValueError('invalid/empty blob verification request')
    paths=list(expected)
    if any('\n' in p or '\r' in p for p in paths):raise ValueError('unsupported path newline')
    raw=checked_run(['git','cat-file','--batch'],data=('\n'.join(commit+':'+p for p in paths)+'\n').encode()).stdout
    pos=0;members=[]
    for p in paths:
        end=raw.find(b'\n',pos)
        if end<0:raise ValueError('missing Git blob header')
        header=raw[pos:end].split();pos=end+1
        if len(header)!=3 or header[1]!=b'blob' or not re.fullmatch(rb'[0-9a-f]{40}',header[0]):
            raise ValueError('missing/nonblob Git member: '+p)
        n=int(header[2]);z=raw[pos:pos+n];pos+=n
        # Empty stdout/stderr is an explicitly hashed valid artifact in negative
        # controls. A missing blob has a different header and remains refused;
        # the expected map itself must still be nonempty. Never infer empty data.
        if n<0 or len(z)!=n or raw[pos:pos+1]!=b'\n':raise ValueError('incomplete Git member: '+p)
        pos+=1;actual=hashlib.sha256(z).hexdigest();kind='strict SHA256'
        if p=='Database/FFXII TZA/_index/_inbox/ASTRA.md' and handoff_bytes is not None:
            if z.replace(b'\r\n',b'\n')!=handoff_bytes.replace(b'\r\n',b'\n'):
                raise ValueError('handoff differs beyond allowed LF normalization')
            kind='LF-only handoff normalization'
        elif actual!=expected[p]:raise ValueError('committed member hash mismatch: '+p)
        members.append(dict(path=p,bytes=n,git_sha256=actual,verification=kind))
    if pos!=len(raw):raise ValueError('unexpected extra Git batch output')
    return members

